void (async () => {
  const { readFile } = require("node:fs/promises");
  const text = await readFile({path}, "utf8");
  console.log(text);
})();

void (async () => {
  const { writeFile } = require("node:fs/promises");
  await writeFile({path}, {data}, {encoding});
})();

void (async () => {
  const { readdir } = require("node:fs/promises");
  const entries = await readdir({path}, {options});
  console.log(entries);
})();

void (async () => {
  const { mkdir } = require("node:fs/promises");
  await mkdir({path}, {options});
})();

void (async () => {
  const { stat } = require("node:fs/promises");
  const info = await stat({path});
  console.log(info.isFile(), info.size);
})();

void (async () => {
  const { rm } = require("node:fs/promises");
  await rm({path}, {options});
})();

void (async () => {
  const { rename } = require("node:fs/promises");
  await rename({oldPath}, {newPath});
})();

void (async () => {
  const { access } = require("node:fs/promises");
  await access({path});
  console.log("accessible");
})();

const { parseArgs } = require("node:util");
const parsed = parseArgs({ config });
console.log(parsed.values, parsed.positionals);

const { createHash } = require("node:crypto");
const digest = createHash({algorithm}).update({data}).digest({encoding});
console.log(digest);

const { EventEmitter } = require("node:events");
const emitter = new EventEmitter();
emitter.on({eventName}, {listener});
emitter.emit({eventName}, {value});

void (async () => {
  const { once } = require("node:events");
  const values = await once({emitter}, {eventName});
  console.log(values);
})();

void (async () => {
  for await (const values of require("node:events").on({emitter}, {eventName})) {
    console.log(values);
    break;
  }
})();

void (async () => {
  const { setTimeout } = require("node:timers/promises");
  console.log(await setTimeout({delay}, {value}));
})();

void (async () => {
  const { setImmediate } = require("node:timers/promises");
  console.log(await setImmediate({value}));
})();

const { gzipSync } = require("node:zlib");
const compressed = gzipSync({data});
console.log(compressed.length);

const { spawnSync } = require("node:child_process");
const result = spawnSync({command}, {args}, {options});
console.log(result.stdout);

const { Buffer } = require("node:buffer");
const bytes = Buffer.from({value}, {encoding});
console.log(bytes);

const { Buffer } = require("node:buffer");
const bytes = Buffer.alloc({size}, {fill});
console.log(bytes);

void (async () => {
  const { pipeline } = require("node:stream/promises");
  await pipeline({source}, {destination});
})();
